def check_r(R, S):
    # Rule (i): If x is removed, so is 2x.
    for x in R:
        if 2*x in S and 2*x not in R:
            return False
    # Rule (ii): If x and y are removed, then x+y is also removed.
    for x in R:
        for y in R:
            if x+y in S and x+y not in R:
                return False
    return True

